function validProject(o){if(o?.format!=='living-geom'||o.version!==1||!o.settings||!Array.isArray(o.cells)||o.cells.length>100000)throw Error('Choose a Living Geom project JSON');if(typeof o.settings.text!=='string'||o.settings.text.length>500)throw Error('Invalid project text');const out={...structuredClone(defaults)};for(const k of Object.keys(out)){if(k==='keys')continue;if(typeof o.settings[k]===typeof out[k])out[k]=o.settings[k]}for(const k of Object.keys(out))if(typeof out[k]==='number'&&!Number.isFinite(out[k]))throw Error('Invalid project values');out.width=Math.max(200,Math.min(2400,out.width));out.height=Math.max(200,Math.min(2400,out.height));out.resolution=Math.max(6,Math.min(80,out.resolution));out.duration=Math.max(1,Math.min(16,out.duration));out.font=out.font.replace(/[";{}<>]/g,'').slice(0,100);out.keys=Array.isArray(o.settings.keys)?o.settings.keys.filter(k=>Number.isFinite(k.t)&&Number.isFinite(k.value)&&k.t>=0&&k.t<=1).slice(0,100):[];for(const k of ['color','accent','background'])if(!/^#[\da-f]{6}$/i.test(out[k]))throw Error('Invalid project color');if(!shapeNames.includes(out.shape))throw Error('Invalid shape');const clean=o.cells.map(p=>{if(!p||typeof p.id!=='string'||!['x','y','ox','oy','col','row'].every(k=>Number.isFinite(p[k])))throw Error('Invalid cell');let c={};for(const k of ['id','x','y','ox','oy','col','row','coverage','locked','shape','size','rotation','opacity','color','motion','intensity','glyph','glyphLabel','blockId','cellSize','accent','pattern','colorMode','flipX','flipY'])if(p[k]!==undefined)c[k]=p[k];if(c.accent&&!/^#[\da-f]{6}$/i.test(c.accent))throw Error('Invalid accent');if(c.cellSize!==undefined&&(!Number.isFinite(c.cellSize)||c.cellSize<1||c.cellSize>200))throw Error('Invalid cell size');if(c.color&&!/^#[\da-f]{6}$/i.test(c.color))throw Error('Invalid cell color');if(c.shape&&!shapeNames.includes(c.shape))throw Error('Invalid cell shape');for(const k of ['size','rotation','opacity','intensity','flipX','flipY'])if(c[k]!==undefined&&!Number.isFinite(c[k]))throw Error('Invalid cell property');return c});const safeBlocks=Array.isArray(o.blocks)&&o.blocks.length?o.blocks.slice(0,50).filter(b=>b&&typeof b.id==='string'&&b.type&&typeof b.type==='object').map(b=>({id:b.id,type:Object.fromEntries(typeKeys.map(k=>[k,typeof b.type[k]===typeof out[k]?b.type[k]:out[k]]))})):[{id:'type-1',type:Object.fromEntries(typeKeys.map(k=>[k,out[k]]))}];if(!safeBlocks.length)throw Error('Invalid type layers');for(const b of safeBlocks){for(const k of typeKeys)if(typeof b.type[k]==='number'&&!Number.isFinite(b.type[k]))throw Error('Invalid layer value');b.type.fontSize=Math.max(30,Math.min(140,b.type.fontSize));b.type.lineHeight=Math.max(.7,Math.min(1.6,b.type.lineHeight));b.type.letterSpacing=Math.max(-8,Math.min(30,b.type.letterSpacing));b.type.resolution=Math.max(6,Math.min(80,b.type.resolution));b.type.density=Math.max(10,Math.min(100,b.type.density));b.type.text=b.type.text.slice(0,500)}for(const p of clean){p.blockId=p.blockId??safeBlocks[0].id;p.glyph=p.glyph??p.blockId+':legacy';p.cellSize=p.cellSize??out.resolution}return{settings:out,cells:clean,blocks:safeBlocks,activeBlock:safeBlocks.some(b=>b.id===o.activeBlock)?o.activeBlock:safeBlocks[0].id,photoData:typeof o.photoData==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(o.photoData)&&o.photoData.length<15e6?o.photoData:null,photoName:typeof o.photoName==='string'?o.photoName.slice(0,180):'',fontData:typeof o.fontData==='string'&&/^data:(font\/|application\/|binary\/)/.test(o.fontData)&&o.fontData.length<7e6?o.fontData:null}}
$('load').onclick=()=>$('project-file').click();$('project-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>25e6)throw Error('Project file is too large');let o=validProject(JSON.parse(await f.text()));push();s=o.settings;cells=o.cells;fontData=o.fontData;blocks=o.blocks;activeBlock=o.activeBlock;photoData=o.photoData;photoName=o.photoName;await restorePhoto();selection.clear();t=0;await loadFontData(false);updateScope();fit();toast('Your exploration is back')}catch(err){toast(err.message||'Unable to open this project')}e.target.value=''};
$('export-open').onclick=()=>$('export-dialog').showModal();$('help-open').onclick=()=>$('help-dialog').showModal();$('export-format').onchange=()=>{const fmt=$('export-format').value;$('export-scale').disabled=['json','svg','sprite'].includes(fmt);$('export-fps').disabled=fmt!=='webm';$('transparent').disabled=['json','webm'].includes(fmt);$('export-note').textContent=fmt==='sprite'?'16 evenly spaced frames in a 4 × 4 PNG sheet, each frame 600 pixels wide.':fmt==='webm'?'Records one cycle in real time. Keep this tab active until the download finishes.':fmt==='svg'?'Vector export preserves geometry and the current motion frame. Raster print effects are omitted.':fmt==='json'?'Includes editable cells, typography, effects, keyframes and your uploaded font.':'Exports the current frame at the selected scale.'};
function exportCanvas(scale=1,transparent=false,time=t){const c=document.createElement('canvas');c.width=Math.round(s.width*scale);c.height=Math.round(s.height*scale);let x=c.getContext('2d');x.scale(scale,scale);render(x,s,cells,time,{transparent,grid:false});return c}function png(c,name){c.toBlob(b=>{if(b)download(b,name);else toast('Image export failed. Try a smaller scale.')},'image/png')}
$('export-go').onclick=async()=>{const format=$('export-format').value,scale=+$('export-scale').value,transparent=$('transparent').checked;if(format==='json'){saveProject();return}if(format==='svg'){download(new Blob([svg(s,cells,t,transparent)],{type:'image/svg+xml'}),'living-geom.svg');return}if(format==='png'){png(exportCanvas(scale,transparent),'living-geom.png');toast('Your frame is ready');return}if(format==='sprite'){const frameW=600,sc=frameW/s.width,frameH=Math.round(s.height*sc),sheet=document.createElement('canvas');sheet.width=frameW*4;sheet.height=frameH*4;const x=sheet.getContext('2d');for(let i=0;i<16;i++){x.save();x.translate(i%4*frameW,Math.floor(i/4)*frameH);x.beginPath();x.rect(0,0,frameW,frameH);x.clip();x.scale(sc,sc);render(x,s,cells,s.duration*i/16,{transparent,grid:false});x.restore()}png(sheet,'living-geom-sprites-4x4.png');toast('16-frame sprite sheet exported');return}if(format==='webm'){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)return toast('Video recording is unavailable in this browser');const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mime)return toast('WebM is not supported here. Export a sprite sheet instead.');let stream,recorder;const wasPlaying=playing;try{exporting=true;playing=false;$('export-go').disabled=true;const c=exportCanvas(Math.min(scale,2),false,0),x=c.getContext('2d'),fps=+$('export-fps').value;stream=c.captureStream(fps);recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:12000000});const chunks=[];const done=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>resolve();recorder.onerror=e=>reject(e.error||Error('Recording failed'))});recorder.start();let start=performance.now();await new Promise(resolve=>{function tick(now){let elapsed=(now-start)/1000,progress=Math.min(elapsed,s.duration);render(x,s,cells,progress,{grid:false});$('export-go').textContent=`Recording… ${Math.round(progress/s.duration*100)}%`;if(elapsed<s.duration)requestAnimationFrame(tick);else resolve()}requestAnimationFrame(tick)});recorder.stop();await done;download(new Blob(chunks,{type:mime}),'living-geom.webm');toast('Your motion loop is ready')}catch{toast('Video export failed. Try a smaller scale or a sprite sheet.')}finally{if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());exporting=false;playing=wasPlaying;$('export-go').disabled=false;$('export-go').textContent='Export artwork ↗';sync()}}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}else if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject()}else if(e.code==='Space'){e.preventDefault();togglePlay()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selection.size){e.preventDefault();if(!e.repeat)push();const d=e.shiftKey?10:1;for(const p of targets()){p.x+=(e.key==='ArrowRight'?d:e.key==='ArrowLeft'?-d:0);p.y+=(e.key==='ArrowDown'?d:e.key==='ArrowUp'?-d:0)}changed()}else if(e.key==='Escape'){selection.clear();updateScope()}else if(e.key==='Delete'||e.key==='Backspace'){if(selection.size){e.preventDefault();push();cells=cells.filter(p=>!selection.has(p.id)||p.locked);selection.clear();updateScope();changed()}}else if(e.key==='Tab'&&document.activeElement===canvas){e.preventDefault();$('focus').click()}});
function renderLayers(){const el=$('type-layers');el.replaceChildren();for(const b of blocks){const btn=document.createElement('button');btn.className='layer-item'+(b.id===activeBlock?' active':'');const name=document.createElement('span'),count=document.createElement('small');name.textContent=b.type.text?.replace(/\n/g,' ')||'Empty type';count.textContent=cells.filter(p=>p.blockId===b.id).length;btn.append(name,count);btn.onclick=()=>{clearTimeout(textTimer);activeBlock=b.id;Object.assign(s,b.type);selection=new Set(cells.filter(p=>p.blockId===b.id).map(p=>p.id));sync();updateScope()};el.append(btn)}$('remove-layer').disabled=blocks.length<2}
function newBlockId(){let id;do{id='type-'+(++blockCounter)}while(blocks.some(b=>b.id===id));return id}
function addBlock(copy=false){clearTimeout(textTimer);if($('text').value!==s.text){s.text=$('text').value.slice(0,500);rebuild()}if(blocks.length>=50)return toast('This project has reached 50 type layers');push();const id=newBlockId(),old=activeBlock;blocks.push({id,type:Object.fromEntries(typeKeys.map(k=>[k,s[k]]))});activeBlock=id;if(copy){cells.push(...cells.filter(p=>p.blockId===old).map(p=>({...p,id:id+':'+p.id,glyph:id+':'+p.glyph,blockId:id,x:p.x+35,y:p.y+35})));changed()}else rebuild();selection=new Set(cells.filter(p=>p.blockId===id).map(p=>p.id));updateScope();toast(copy?'Type layer duplicated':'New independent type layer. Change its text or move it.')}
$('add-layer').onclick=()=>addBlock();$('duplicate-layer').onclick=()=>addBlock(true);$('remove-layer').onclick=()=>{if(blocks.length<2)return;push();cells=cells.filter(p=>p.blockId!==activeBlock);blocks=blocks.filter(b=>b.id!==activeBlock);activeBlock=blocks.at(-1).id;Object.assign(s,blocks.at(-1).type);selection.clear();updateScope();changed()};
canvas.addEventListener('dblclick',e=>{if(tool!=='select'&&tool!=='move')return;const p=hit(coords(e));if(!p)return;selection=new Set(cells.filter(c=>c.glyph===p.glyph&&c.blockId===p.blockId).map(c=>c.id));updateScope();toast(`Glyph selected · ${selection.size} cells`)});
function transformSelection(scale=1,degrees=0,flipX=1,flipY=1){const chosen=targets().filter(p=>selection.has(p.id));if(!chosen.length)return;push();const cx=(Math.min(...chosen.map(p=>p.x))+Math.max(...chosen.map(p=>p.x)))/2,cy=(Math.min(...chosen.map(p=>p.y))+Math.max(...chosen.map(p=>p.y)))/2,r=degrees*Math.PI/180;for(const p of chosen){const dx=(p.x-cx)*scale*flipX,dy=(p.y-cy)*scale*flipY;p.x=cx+dx*Math.cos(r)-dy*Math.sin(r);p.y=cy+dx*Math.sin(r)+dy*Math.cos(r);p.size=Math.max(.05,(p.size??s.size)*scale);p.flipX=(p.flipX??1)*flipX;p.flipY=(p.flipY??1)*flipY;p.rotation=(p.rotation??s.rotation)*flipX*flipY+degrees}changed();sync()}
$('group-smaller').onclick=()=>transformSelection(.85);$('group-bigger').onclick=()=>transformSelection(1/.85);$('group-left').onclick=()=>transformSelection(1,-15);$('group-right').onclick=()=>transformSelection(1,15);$('group-flip-x').onclick=()=>transformSelection(1,0,-1,1);$('group-flip-y').onclick=()=>transformSelection(1,0,1,-1);$('duplicate-selection').onclick=()=>{if(!selection.size)return;push();const token='copy-'+Date.now();const copy=targets().map(p=>({...p,id:token+':'+p.id,glyph:token+':'+p.glyph,x:p.x+32,y:p.y+32}));cells.push(...copy);selection=new Set(copy.map(p=>p.id));changed();updateScope()};
let photoToken=0;async function restorePhoto(){const token=++photoToken;if(!photoData){setPhoto(null);$('photo-name').textContent='Your photo stays in this browser and travels with your saved project.';dirty=true;return}const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=photoData});if(token!==photoToken)return;setPhoto(img,photoData);$('photo-name').textContent=photoName||'Background photograph';dirty=true}
$('photo-upload').onclick=()=>$('photo-file').click();$('photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20e6){toast('Choose a photo smaller than 20 MB');e.target.value='';return}try{const image=await createImageBitmap(file),scale=Math.min(1,2400/Math.max(image.width,image.height)),c=document.createElement('canvas');c.width=Math.round(image.width*scale);c.height=Math.round(image.height*scale);c.getContext('2d').drawImage(image,0,0,c.width,c.height);image.close();push();photoData=c.toDataURL('image/jpeg',.92);photoName=file.name;Object.assign(s,{photoScale:1,photoX:0,photoY:0,photoOpacity:1,photoVisible:true});await restorePhoto();changed();sync();toast('Photo added. Arrange your type around it.')}catch{toast('Could not open this photo. Try JPG, PNG or WebP.')}e.target.value=''};
$('photo-fit').onclick=()=>{push();Object.assign(s,{photoScale:1,photoX:0,photoY:0});changed();sync()};$('photo-remove').onclick=()=>{push();photoData=null;photoName='';setPhoto(null);restorePhoto();changed()};$('modular-style').onclick=()=>applyPreset(18);
