try{const saved=localStorage.getItem('living-geom-latest');if(saved){const b=document.createElement('button');b.className='quiet full';b.textContent='↶ Restore last saved session';b.onclick=async()=>{try{const o=validProject(JSON.parse(saved));push();s=o.settings;cells=o.cells;fontData=o.fontData;blocks=o.blocks;activeBlock=o.activeBlock;photoData=o.photoData;photoName=o.photoName;await restorePhoto();await loadFontData(false);selection.clear();updateScope();fit();toast('Last saved session restored')}catch{toast('Could not restore saved session')}};$('tab-type').append(b)}}catch{}
